message.value:
@concat(
    'Invalid run type: ',
    variables('v_run_type'),
    '. Supported values are REGULAR, RERUN, BACKFILL.'
)

expression.value:
@not(
    or(
        and(
            equals(
                activity('lkp_ingestion_config').output.value[0].load_strategy,
                'FULL'
            ),
            equals(
                variables('v_run_type'),
                'BACKFILL'
            )
        ),
        and(
            and(
                equals(
                    activity('lkp_ingestion_config').output.value[0].ingestion_pattern,
                    'FILE'
                ),
                equals(
                    activity('lkp_ingestion_config').output.value[0].load_strategy,
                    'INCREMENTAL'
                )
            ),
            not(
                equals(
                    variables('v_run_type'),
                    'REGULAR'
                )
            )
        )
    )
)

value.value:
@if(
    and(
        equals(
            activity('lkp_ingestion_config').output.value[0].ingestion_pattern,
            'FILE'
        ),
        equals(
            activity('lkp_ingestion_config').output.value[0].load_strategy,
            'INCREMENTAL'
        )
    ),
    'FILE INCREMENTAL currently supports REGULAR runs only. File replay is controlled by file identity rather than relational LOW/HIGH boundaries.',
    'BACKFILL is not supported for FULL load strategy.'
)

message.value:
@if(
    and(
        equals(
            activity('lkp_ingestion_config').output.value[0].ingestion_pattern,
            'FILE'
        ),
        equals(
            activity('lkp_ingestion_config').output.value[0].load_strategy,
            'INCREMENTAL'
        )
    ),
    'FILE INCREMENTAL currently supports REGULAR runs only. File replay is controlled by file identity rather than relational LOW/HIGH boundaries.',
    'BACKFILL is not supported for FULL load strategy.'
)

expression.value:
@if(
    and(
        and(
            equals(
                activity('lkp_ingestion_config').output.value[0].ingestion_pattern,
                'DATABASE'
            ),
            equals(
                activity('lkp_ingestion_config').output.value[0].load_strategy,
                'INCREMENTAL'
            )
        ),
        or(
            equals(variables('v_run_type'), 'RERUN'),
            equals(variables('v_run_type'), 'BACKFILL')
        )
    ),
    and(
        not(empty(pipeline().parameters.p_requested_lower_bound)),
        not(empty(pipeline().parameters.p_requested_upper_bound))
    ),
    and(
        empty(pipeline().parameters.p_requested_lower_bound),
        empty(pipeline().parameters.p_requested_upper_bound)
    )
)
